  ["Mejora la eficiencia en combate (gastas menos Mana)."] = "Improves combat efficiency (you spend less Mana).",
  ["Mejora todas tus sanaciones."] = "Improves all of your heals.",
  ["Mejora tu Rage (más Maul al subir) y baja el costo de Energy en Cat Form."] = "Improves your Rage (more Maul while leveling) and lowers the Energy cost in Cat Form.",
  ["Mejora tu manejo del maná."] = "Improves your Mana management.",
  ["Mejora tu probabilidad de golpear un 1/2/3/4/5% y reduce la amenaza generada un 4/8/12/16/20%."] = "Improves your chance to hit by 1/2/3/4/5% and reduces all threat you generate by 4/8/12/16/20%.",
  ["Mejora un 1/2/3% tu probabilidad de golpear."] = "Improves your chance to hit by 1/2/3%.",
  ["Mejora un 1/2/3/4/5% tu probabilidad de asestar un golpe crítico con ataques cuerpo a cuerpo."] = "Improves your chance to get a critical strike with melee attacks by 1/2/3/4/5%.",
  ["Mejora un 1/2/3/4/5% tu probabilidad de golpear con hechizos de las Sombras."] = "Improves your chance to hit with Shadow spells by 1/2/3/4/5%.",
  ["Mejora un 1/2/3/4/5% tu probabilidad de obtener un golpe crítico con todos tus hechizos y ataques."] = "Improves your chance to get a critical strike with all spells and attacks by 1/2/3/4/5%.",
  ["Mejora un 2/4/6% tu probabilidad de golpear con todos los hechizos."] = "Improves your chance to hit with all spells by 2/4/6%.",
  ["Mejora un 2/4/6% tu probabilidad de obtener un golpe crítico con todos tus hechizos y ataques."] = "Improves your chance to get a critical strike with all spells and attacks by 2/4/6%.",
  ["Mejora un 4/8% tu probabilidad de golpear con hechizos Sagrados, y reduce un 10/20% la duración de los efectos de Silencio que sufres."] = "Improves your chance to hit with Holy spells by 4/8%, and reduces the duration of Silence effects on you by 10/20%.",
  ["Mejora un 6/12/18% tu probabilidad de golpear con hechizos Sagrados."] = "Improves your chance to hit with Holy spells by 6/12/18%.",
  ["Mejoras para ti a nivel "] = "Upgrades for you at level ",
  ["Melee weapon (solo por estadísticas)"] = "Melee weapon (for stats only)",
