  ["Tailoring de 75 a 150: Woolen Cape ×30 (75→98), Double-stitched Woolen Shoulders ×37 (98→128), Gloves of Meditation ×18 (128→140), Bolt of Mageweave ×9 (140→148), Red Swashbuckler's Shirt ×6 (148→153)."] = "Tailoring from 75 to 150: Woolen Cape ×30 (75→98), Double-stitched Woolen Shoulders ×37 (98→128), Gloves of Meditation ×18 (128→140), Bolt of Mageweave ×9 (140→148), Red Swashbuckler's Shirt ×6 (148→153).",
  ["Tailoring de 75 a 150: Woolen Cape ×51 (76→106), Red Woolen Bag ×4 (106→110), Double-stitched Woolen Shoulders ×25 (110→128), Red Woolen Bag ×9 (128→133), Gloves of Meditation ×23 (133→145) y 1 tramos más."] = "Tailoring from 75 to 150: Woolen Cape ×51 (76→106), Red Woolen Bag ×4 (106→110), Double-stitched Woolen Shoulders ×25 (110→128), Red Woolen Bag ×9 (128→133), Gloves of Meditation ×23 (133→145) and 1 more steps.",
  ["Tailoring: la tela la sueltan los humanoides (no las bestias) de tu nivel; las mazmorras dan mucha."] = "Tailoring: cloth drops from humanoids (not beasts) of your level; dungeons give a lot.",
  ["Talento"] = "Talent",
  ["Talento de 31 puntos (el último de tu rama). Montura: las monturas de la beta piden nivel 40 (las épicas, 60)."] = "31-point talent (the last one in your spec). Mount: beta mounts require level 40 (epic ones, 60).",
