  ["Unyielding Faith (2 puntos)"] = "Unyielding Faith (2 points)",
  ["Usa /wowf objetivo fabricar, /wowf objetivo oro o /wowf objetivo pvp."] = "Use /wowf goal craft, /wowf goal gold or /wowf goal pvp.",
  ["Utilidad para ti mismo: Guns y Scopes (Hunter), cascos, granadas, reflectores y Trinkets."] = "Utility for yourself: Guns and Scopes (Hunter), helms, grenades, reflectors and Trinkets.",
